def solve():
    for n in range(1, 20):
        s_n = 0
        for a in range(1, n + 1):
            for b in range(1, n + 1):
                s_n += (a * b) // (n + 1)

        formula = (n**3 - n**2 + 2) / 4
        if s_n == formula:
            print(f"N={n}: S(N)={s_n}, formula={formula}")
        else:
            print(f"N={n}: S(N)={s_n}, formula={formula}")

