from math import gcd

def phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def f(m):
    res = 0
    for d in range(1, int(m**0.5) + 1):
        if m % d == 0:
            res += d * phi(m // d)
            if d*d != m:
                res += (m // d) * phi(d)
    return res

for m in range(2, 1000):
    if f(m) == 2 * m:
        print(f"m={m}")
